/* Original beginner scaffolds. Source links are rendered in course endnotes. */
function conceptLesson(id,title,body,example,question,right,wrong,reason,source,pages){return {id,section:'先建立概念',title,summary:body[0],body,examples:[{text:example,meaning:reason}],related:reason,diagram:'',source,tasks:[choiceTask(question,right,wrong,reason)],quiz:choiceTask(question,right,wrong,reason,1),teachingPages:pages,reminder:'先对照例子理解差别，不用背术语。',transfer:example+'\n'+reason};}
const jpText=conceptLesson('jp-start-scripts','日语文字：先分清三种写法',['日语常把平假名、片假名和汉字混合使用。假名主要表音，汉字常承载词义；不是每个日语汉字都按中文读。','罗马字用拉丁字母辅助标音，是起步工具，不是日语唯一书写方式。'], 'ねこ / ネコ / 猫 → 这里都可表示“猫”，写法与使用场景不同。','假名主要帮我们表示什么？','日语的读音',['文件权限','英语原词拼写'],'先把字形与读音对应，再学词和句。',['日本国际交流基金《彩》','https://www.jpfbj.cn/irodori/'],[
 P('你会看到什么文字？',['平假名如 あ、い、う，片假名如 ア、イ、ウ，汉字如 山、猫。它们经常出现在同一句话里。','先认识三种文字，不要求现在记住全部发音。'],'猫はかわいいです。\n猫 是汉字；は、かわいい、です 是平假名。','',['假名']),
 P('两套假名，读音常对应',['あ 与 ア、い 与 イ，分别是同一基础读音的两套字形。平假名常用于词尾和语法部分，片假名常用于外来词、拟声词或强调。','这些是常见用途，不是所有句子的绝对规则。不要只根据外形猜词义。'],'あ ↔ ア\nい ↔ イ\nカメラ → 相机','',['片假名','平假名']),
 P('汉字不能直接照中文念',['相同汉字可能有不同语言中的读音和意义。日语汉字还有不同读法，读词时应结合词汇。','先看提供的假名读音，再听合成发音或官方真人音频；设备合成语音不是全部口音和语境的标准答案。'],'猫 → ねこ（neko）\n罗马字 neko 只是帮助你建立读音。','',['汉字'])
]);
const jpMora=conceptLesson('jp-start-mora','日语的拍：用节奏理解声音',['拍是日语节奏的基本单位，可以用均匀拍手帮助体会。普通假名常占一拍，促音、长音和拨音也占拍。','两个字形不总等于两拍：小写 ゃ 与前一个假名形成拗音，例如 きゃ 是一拍。'],'ねこ：ね・こ，两拍\nきって：き・っ・て，三拍','きって 的小っ能直接忽略吗？','不能，它占一拍并改变读音节奏',['能，它只是装饰','能，所有小假名都不发作用'],'节奏差异可能改变词义，先慢速数拍再听音。',['日本国际交流基金《彩》','https://www.jpfbj.cn/irodori/'],[
 P('一拍一拍读',['用均匀节奏读 ね・こ，每个位置占一拍。拍不是中文声调，也不总等于英语里的一个音节。'],'ね・こ → 两拍\nす・し → 两拍','',['拍']),
 P('小っ不是多余字符',['きて 与 きって 不同。小っ表示促音，在相应位置保留一拍闭塞或停顿，具体发音结合后面的辅音。','听不清时先看词形、数拍，再对照官方音频。'],'き・て → 来吧\nき・っ・て → 邮票','',['促音']),
 P('现在只带走一个习惯',['看到小假名或长音，不要直接跳过。先判断它和前后哪个音组合，再慢速听读。','下一课从 あいうえお 的字形与读音开始，不一口气要求记住全部语法。'],'认形 → 数拍 → 听音 → 再读词','',['拗音'])
]);
hubCurriculum.japanese.unshift(jpText,jpMora);
const firstAgent=hubCurriculum.agent[0];firstAgent.teachingPages=[
 P('模型：先把它理解成处理输入的组件',['语言模型根据输入生成文字等内容。你提出问题，它生成回答；这不等于它已经连接了你的数据库或执行了命令。','输出看起来合理也可能出错。实际工作要区分建议、事实和工具证据。'],'问“服务正常吗？” → 模型文字回答\n调用状态工具 → 应用返回实际结果','',['模型']),
 P('工具：真的做事的是谁？',['工具是应用提供的具体能力，例如读取文件、查询状态。模型可以提出调用请求，由应用检查参数和权限后实际执行。','工具有范围、权限与错误结果；模型说“已完成”不能替代工具日志。'],'模型建议 → 应用校验 → 工具执行 → 返回结果','',['工具','权限']),
 P('Agent 与固定工作流',['固定工作流按预先设计的步骤走，Agent 在限定目标、工具和状态内根据反馈选择下一步。二者都需要停止条件和验证。','不是加上 Agent 名字就能拥有无限权限，也不是越复杂越适合新手。'],'目标：查测试服务状态\n观察：请求超时\n下一步：按许可读取日志，或停止并说明','',['Agent','工作流']),
 P('从一个只读任务开始',['先做“查询并返回证据”，明确输入、工具、输出和失败出口，再逐步加入更复杂操作。','后续学 RAG、MCP、记忆与编排时，仍沿用这个原则。'],'完成标准：状态 + 查询时间 + 来源\n失败标准：无权限、工具失败、达到预算','',['RAG','MCP'])
];
const firstWriting=hubCurriculum.writing[0];firstWriting.teachingPages=[
 P('先读发生了什么',['阅读不是先背分析术语。先找出人物、地点、事情和变化，用自己的话说一遍。','你看到的原文信息与自己的猜测需要分开记。'],'原文：他在门口等了一小时。\n事实：等待了一小时。\n猜测：他也许焦虑；还需上下文证据。'),
 P('谁说的，谁知道？',['人物是故事里做事的人，叙述者是讲故事的声音，作者是写作品的人。三者不必相同。','第一人称“我”可能是虚构人物，也可能只知道一部分事实。'],'作者 → 创作作品\n叙述者 → 讲述故事\n人物 → 在故事中行动','',['叙述者']),
 P('写第一条阅读记录',['只记录一个问题、一处证据和一个暂时解释。带上章节或位置，方便下次回看。','先写清楚，不追求一开始就给作品下大结论。'],'问题：他为什么等待？\n证据：第 1 章，门口等待一小时。\n解释：可能有约定；后文继续确认。')
];
pythonLessons[0].teachingPages=[
 P('Python 代码在哪里运行？',['Python 是编程语言。解释器读取并运行代码；本站在浏览器隔离环境里运行真实 Python，无需你先安装。','终端命令和 Python 代码的语法不同。print("hello") 是 Python 代码，不要在普通 Shell 中当作同一条命令照搬。'],'教学代码编辑区 → Python 解释器 → 输出结果','',['解释器','Python']),
 P('把 print 拆开看',['print 是 Python 内置函数的名字；后面的括号表示调用它，括号内放要显示的值。','"hello" 用引号表示字符串。引号属于代码语法，输出通常只显示里面的内容。'],'print("hello")\n输出：hello','',['函数','字符串']),
 P('输入、输出、错误是三件事',['输入是你写的代码；输出是运行时显示的结果；错误消息说明代码没能按要求继续。','漏掉引号或括号可能造成语法错误。不要把错误原文复制进代码当成解决办法。'],'print("hello")  → 正确\nprint("hello)   → 引号未闭合','',['语法错误']),
 P('示例和任务不必一样',['示例展示语法，任务要求你把这个写法用在新的内容上。不要只记住一段固定文本。','运行成功后看输出是否符合任务，再确认结果，最后用小测解释自己做了什么。'],pythonLessons[0].example),
 P('现在轮到你',['下面是本课任务。先按要求修改字符串，再运行；任务结果和检查条件仍以原课堂为准。'],pythonLessons[0].task)
];
Object.assign(beginnerTerms,{平假名:'日语的一套表音文字，常用于语法部分、词尾等；与片假名有基础读音对应关系。',片假名:'日语的另一套表音文字，常用于外来词、拟声词与强调；不按英语原词拼写直接发音。',汉字:'日语中常承载词义的文字，读音要结合词汇；不能全部照中文念。',拍:'日语节奏的基本单位。普通假名、长音、促音、拨音等要按规则计拍，小假名不一定单独占拍。',模型:'接收输入并生成预测或内容的计算组件；生成文字不等于已经执行实际操作。',工具:'应用提供的具体功能，例如查询状态或读取文件。调用需要校验参数和权限，结果需要验证。',工作流:'应用预先安排的步骤及其状态转移，强调每步输入、动作、结果和失败出口。',叙述者:'作品中讲述故事的声音，不一定是作者本人，也不一定知道全部事实。',解释器:'读取并运行程序代码的运行环境，例如 Python 解释器；编辑器负责写代码，两者分工不同。',Python:'一种编程语言，适合脚本、数据处理和自动化。本课堂在浏览器隔离环境实际运行。',语法错误:'代码写法不符合语言规则，例如引号或括号未闭合，解释器因此无法按正常逻辑运行。'});
const sqlPreparations=[
 conceptLesson('sql-start-table','数据库先认识表、行、列',['数据库管理结构化数据。表是一类数据的集合，行是一条记录，列是记录里的属性；页面的显示字段与数据库列不一定同名。','schema 是组织对象的逻辑命名空间。APP.ORDERS 在本课中表示 APP 下的 ORDERS；先分清账号、schema 与表，再查数据。'],'APP.ORDERS\nID | ORDER_NO | STATUS\n1  | A-001    | PAID\n2  | A-002    | NEW','一条订单记录在表里通常对应什么？','一行记录',['一个文件夹','整个数据库实例'],'行是记录，列是属性；页面还可能组合多张表。',['达梦官方文档','https://eco.dameng.com/document/dm/zh-cn/faq/faq-db-check'],[
 P('像表格，但不是页面截图',['列有名字与类型，例如 ID、ORDER_NO、STATUS；一行给这些列各一个值。','界面中的订单号可能经过接口、代码或多个表组合，不能直接根据页面中文标题猜表名。'],'ID | ORDER_NO | STATUS\n1  | A-001    | PAID\n2  | A-002    | NEW','',['表','行','列']),
 P('账号、schema、表分别是什么？',['账号涉及连接身份与权限；schema 组织对象；表保存一类记录。默认 schema 不符合预期时，未限定表名可能指向别处或找不到。'],'APP.ORDERS → APP 下的 ORDERS\nORDERS → 由当前数据库对象解析规则确定','',['数据源','schema']),
 P('先读元数据，再看样本',['元数据告诉你对象名、列类型和注释，业务样本帮助确认是不是目标数据。','真实系统按权限查询最小范围，避免直接扫描全部业务数据。'],'查表与列 → 核对接口/代码 → 只读样本验证','',['元数据','数据字典'])
 ]),
 conceptLesson('sql-start-select','SELECT：查哪些列、哪张表、哪些行',['SELECT 列出要返回的列，FROM 指定数据来源，WHERE 给筛选条件。字符串常用单引号；SQL 关键字与业务文本的大小写要分别理解。','这是语法理解课，不执行真实查询。后续 DM8 课才在固定教学数据上验证支持的语句。'],"SELECT ORDER_NO, STATUS\nFROM APP.ORDERS\nWHERE STATUS = 'PAID'","WHERE STATUS = 'PAID' 在这里做什么？",'筛选状态为 PAID 的记录',['删除所有 PAID 记录','切换当前 Linux 用户'],'SELECT 读取，WHERE 筛选；它们不是文件命令。',['达梦官方文档','https://eco.dameng.com/document/dm/zh-cn/faq/faq-db-check'],[
 P('把查询拆成三个问题',['SELECT：我需要哪些列？FROM：从哪个对象读？WHERE：哪些行符合条件？','一次写清对象和条件，比复制很长的 SQL 更容易检查。'],"SELECT ORDER_NO, STATUS\nFROM APP.ORDERS\nWHERE STATUS = 'PAID'",'',['SQL','字段']),
 P('引号包的是业务值',['PAID 是本课业务状态字符串，单引号把它表示为一个文本值。逗号分隔要返回的列。','SQL 的比较符 = 与 Python 赋值符 = 属于不同语法环境。不要把不同语言的符号用法直接交换。'],"ORDER_NO, STATUS → 两列\nSTATUS = 'PAID' → 本课的等值筛选条件",'',['字符串','类型']),
 P('查询成功还要验证什么？',['能执行只证明数据库接受了这条查询，不能保证你选对表、schema、时间范围或业务状态。','接下来查元数据与页面对应关系，用少量只读样本判断是否找对对象。'],'对象 → 条件 → 输出列 → 样本 → 与页面核对','',['schema','数据源'])
 ])
];
// Introduce configuration formats before deployment and SQL syntax before DM8.
const workBefore=hubCurriculum.opswork.slice(),formats=workBefore.filter(c=>['git','yaml','json'].includes(c.id));
const workRest=workBefore.filter(c=>!['git','yaml','json'].includes(c.id));
const commandEnd=workRest.findIndex(c=>!c.id.startsWith('cmd-start-'));
workRest.splice(commandEnd,0,...formats);
const dmStart=workRest.findIndex(c=>c.section==='DM8 与业务数据');
workRest.splice(dmStart<0?workRest.length:dmStart,0,...sqlPreparations);
hubCurriculum.opswork=workRest;
